id: rifts-dwarf
name: Dwarf
system: rifts
source_book: Rifts Conversion Book One p.84-86
category: rcc
men_of_arms: false
attribute_dice:
  IQ: "3d6"
  ME: "3d6"
  MA: "2d6"
  PS: "4d6+6"
  PP: "3d6"
  PE: "4d6"
  PB: "2d6+2"
  Spd: "2d6"
hit_points_base: "P.E. + 1D6 per level"
ppe_base: "3d6"
bonuses:
